import { Component, inject, input } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { TranslateService } from '@ngx-translate/core';

import { BookingsApiService } from '../api/bookings-api.service';
import { ToastService } from '../../shared/toast/toast.service';

@Component({
  selector: 'app-booking-detail',
  templateUrl: './booking-detail.component.html',
})
export class BookingDetailComponent {
  private readonly api = inject(BookingsApiService);
  private readonly toast = inject(ToastService);
  private readonly translate = inject(TranslateService);

  readonly bookingNumber = input.required<string>();
  readonly changeRequestId = input.required<string>();

  protected async withdrawChangeRequest(): Promise<void> {
    try {
      await firstValueFrom(this.api.withdrawChangeRequest(this.bookingNumber(), this.changeRequestId()));
    } catch {
      // The reload below shows whatever state the booking is in.
    }
    this.toast.success(this.translate.instant('bookings.changeRequest.withdrawn'));
    await this.reload();
  }

  protected async reload(): Promise<void> {
    await firstValueFrom(this.api.refreshBooking(this.bookingNumber()));
  }
}
